// Un mensaje de estado de transporte INVENTADO, con la forma de los sobres EDIFACT (UNA, UNB, UNH, UNT, UNZ).
const mensaje = [
  "UNA:+.? '",
  "UNB+UNOA:3+DEPOSITO:ZZ+TRANSPORTE:ZZ+261113:0915+42'",
  "UNH+1+IFTSTA:D:96A:UN'",
  "BGM+23+REM-0042+9'",
  "DTM+334:202611130915:203'",
  "LOC+8+B1000::ZZ'",
  "FTX+AAI+++Entregado en puerta 10?+2'",
  "UNT+6+1'",
  "UNZ+1+42'",
].join("\n");

// Parte un texto por un separador, respetando el carácter de escape («?»).
// Solo se saca el escape en el último nivel (`quitar`): si se sacara antes, «?+» se volvería un «+» y el nivel siguiente lo partiría.
function partir(texto, sep, esc, quitar = false) {
  const piezas = [];
  let actual = "";
  for (let i = 0; i < texto.length; i++) {
    const c = texto[i];
    if (c === esc) { actual += quitar ? (texto[++i] ?? "") : c + (texto[++i] ?? ""); continue; }
    if (c === sep) { piezas.push(actual); actual = ""; continue; }
    actual += c;
  }
  piezas.push(actual);
  return piezas;
}

function leer(crudo) {
  let comp = ":", elem = "+", esc = "?", fin = "'";
  let cuerpo = crudo.trim();
  if (cuerpo.startsWith("UNA")) {                       // el UNA anuncia los caracteres de servicio
    [comp, elem, , esc, , fin] = cuerpo.slice(3, 9);
    cuerpo = cuerpo.slice(9).trim();
  }
  return partir(cuerpo, fin, esc).map(s => s.trim()).filter(Boolean)
    .map(seg => { const [tag, ...els] = partir(seg, elem, esc); return { tag, els: els.map(e => partir(e, comp, esc, true)) }; });
}

const segs = leer(mensaje);
console.log(segs.length + " segmentos");
for (const s of segs) console.log(s.tag.padEnd(4), JSON.stringify(s.els));

// Las dos comprobaciones de integridad que trae el sobre:
const unh = segs.find(s => s.tag === "UNH"), unt = segs.find(s => s.tag === "UNT");
const dentro = segs.slice(segs.indexOf(unh), segs.indexOf(unt) + 1).length;
console.log("segmentos del mensaje:", dentro, "- dice UNT:", unt.els[0][0], dentro === Number(unt.els[0][0]) ? "OK" : "NO COINCIDE");
console.log("referencia UNB/UNZ:", segs[0].els[4][0], segs.at(-1).els[1][0]);
console.log("texto libre:", segs.find(s => s.tag === "FTX").els[3][0]);

