// Tres sistemas hablan tres formatos. En el medio, un modelo canónico: { remito, fecha, detalle, origen }.
// Datos inventados. Un traductor por formato; los que escuchan solo conocen el modelo canónico.
const traductores = {
  edifact(txt) {                                    // versión mínima: sin respetar escapes ni la UNA
    const seg = Object.fromEntries(txt.split("'").map(s => s.trim().split("+")).filter(p => p[0]).map(p => [p[0], p]));
    const f = seg.DTM[1].split(":")[1];             // 202611130915
    return { remito: seg.BGM[2], fecha: `${f.slice(0, 4)}-${f.slice(4, 6)}-${f.slice(6, 8)}T${f.slice(8, 10)}:${f.slice(10, 12)}`, detalle: seg.FTX[4] };
  },
  csv(linea) {                                      // «remito;dd/mm/aa;hh:mm;detalle»
    const [remito, dia, hora, detalle] = linea.split(";");
    const [d, m, a] = dia.split("/");
    return { remito: "REM-" + remito, fecha: `20${a}-${m}-${d}T${hora}`, detalle };
  },
  json(o) { return { remito: "REM-" + o.id, fecha: o.ts.slice(0, 16), detalle: o.note }; },
};

function detectar(msg) {
  if (typeof msg === "object") return "json";
  if (msg.startsWith("UNB") || msg.startsWith("UNA")) return "edifact";
  if (msg.split(";").length === 4) return "csv";
  return null;
}

const escuchas = [];
const cartaMuerta = [];                              // lo que no se entiende no se pierde: se aparta para que alguien lo mire
function publicar(msg) {
  const formato = detectar(msg);
  try {
    const canonico = { ...traductores[formato](msg), origen: formato };
    escuchas.forEach(f => f(canonico));
  } catch (e) {
    cartaMuerta.push({ msg, motivo: formato ? "falló el traductor " + formato : "formato desconocido" });
  }
}

